export const BODY: string = "\n<p>كل قص له نسبة، سواء اخترتها أم لا: النسبة هي شكل المستطيل الذي تحتفظ به، وتقرر أين تناسب الصورة وكيف تبدو.</p>\n<p>قص مربع وقص واسع ليسا قابلين للتبادل: واحد يناسب صورة شخصية، والآخر يناسب لافتة، واستخدام الخطأ يعني أن المنصة ستعيد قص عملك نيابة عنك.</p>\n<p>يشرح هذا المقال النسب الشائعة وما تنفع له كل منها وكيف تختار: ويغطي أيضًا النسب المخصصة والرياضيات خلفها وأخطاء تنشأ من تجاهلها. وإذا أردت التجربة، جرّب <a href=\"/ar/qass-as-suwar/\">قصاص الصور</a> في متصفحك.</p>\n<h2 id=\"what-is-an-aspect-ratio\">ما النسبة؟</h2>\n<p>النسبة هي العلاقة بين عرض صورة وارتفاعها، مكتوبة كرقمين بينهما نقطتان، مثل 16:9.</p>\n<p>الأرقام تصف تناسبًا لا عدد بكسلات: صورة 16:9 قد تكون 1920 في 1080 بكسلًا أو 1280 في 720 بكسلًا، وكلتاهما بنفس الشكل. ولإيجاد نسبة أي صورة، اقسم العرض على الارتفاع: صورة بعرض 1200 بكسل وارتفاع 800 لها نسبة 1.5، وهي نفسها 3:2.</p>\n<p>والنسب مهمة لأن الوجهات تطلب أشكالًا: منصة تريد مربعًا ستقص صورة واسعة، وطابعة تريد 4:3 ستمد أو تقص أي شيء آخر.</p>\n<h2 id=\"ratio-1-1\">1:1: المربع</h2>\n<p>نسبة 1:1 تعني أن العرض والارتفاع متساويان، فالصورة مربع مثالي: إنها النسبة الأكثر شيوعًا في وسائل التواصل الاجتماعي، وتُستخدم لصور شخصية ومنشورات في شبكة.</p>\n<p>المربعات تشعر بالتوازن والحياد: تناسب صورًا شخصية وصور منتج وأي شيء يجب أن يناسب شبكة دون تفضيل اتجاه. والمشكلة أن معظم المنصات تعرض صورًا شخصية مربعة كدوائر: زوايا مربعك تُقص، فأبقِ الوجه داخل الإطار جيدًا.</p>\n<p>وعند القص إلى 1:1، ركّز الشخص مع مساحة قليلة أعلاه: وجه يلمس الحافة العلوية سيفقد شعره بالقص الدائري، وشخص في الزاوية سيُقص تمامًا.</p>\n<h2 id=\"ratio-4-3\">4:3: شكل الصورة الكلاسيكي</h2>\n<p>نسبة 4:3 أعرض قليلًا من ارتفاعها: كانت الشكل القياسي لشاشات التلفاز وكاميرات رقمية مبكرة، وما زالت تناسب صورًا تقليدية.</p>\n<p>إنها خيار افتراضي جيد لوثائق وصفحات ممسوحة، حيث المحتوى أعرض من مربع لكنه ليس واسعًا كإطار فيديو: وتُطبع جيدًا أيضًا في أحجام ورق قياسية. وكثير من كاميرات الهواتف ما زالت توفر وضع 4:3: وإذا كانت كاميرتك تصور بهذه النسبة، فالقص إلى 4:3 يحافظ على الإطار الكامل دون إزالة شيء تقريبًا.</p>\n<p>استخدم 4:3 عندما يحتاج الشخص مساحة أفقية قليلة لكن الصورة لا يجب أن تشعر بالبانوراما: صورة جماعية أو داخل أو وثيقة تناسب هذا الشكل.</p>\n<h2 id=\"ratio-3-2\">3:2: معيار الكاميرا</h2>\n<p>نسبة 3:2 تأتي من كاميرات فيلم 35 ملم، وما زالت الشكل الافتراضي لمعظم كاميرات DSLR وبلا مرآة: أعرض من 4:3 لكنها أضيق من 16:9.</p>\n<p>تناسب مناظر وتصوير شوارع، حيث العرض الإضافي يعطي المشهد مساحة للتنفس دون تحويل الصورة إلى بانوراما. وأحجام الطباعة غالبًا تطابق هذه النسبة: طباعة 6 في 4 بوصات هي بالضبط 3:2، فصورة مقصوصة إلى هذا الشكل تُطبع دون مزيد من القص.</p>\n<p>وإذا كانت كاميرتك تصور في 3:2 وتطبع كثيرًا، أبقِ قصاصاتك في هذه النسبة: ستتجنب مفاجأة أن المختبر يقطع حواف صورتك المفضلة.</p>\n<h2 id=\"ratio-16-9\">16:9: الشاشة العريضة</h2>\n<p>نسبة 16:9 هي شكل الشاشات الحديثة: تلفاز وشاشات وشاشات هواتف في وضع أفقي: إنها واسعة وسينمائية ومصنوعة لمحتوى يمتد عبر شاشة.</p>\n<p>إنها الخيار الصحيح لمصغرات فيديو ولافتات مواقع وشرائح عروض: قص 16:9 يملأ المساحة دون أشرطة فارغة في أي جانب. والعيب هو المساحة العمودية: قص 16:9 من صورة طويلة يتخلص من بكسلات كثيرة أعلاه وأسفله، فيجب أن يناسب الشخص شريطًا رفيعًا بارتياح.</p>\n<p>أبقِ المحتوى المهم في وسط قص 16:9: المنصات غالبًا تقص الجانبين مجددًا للهاتف، فأي شيء قرب الحافة اليسرى أو اليمنى قد يختفي.</p>\n<h2 id=\"ratio-4-5-and-9-16\">4:5 و9:16: الأشكال العمودية</h2>\n<p>النسب العمودية مهمة لأن معظم الناس يرون المحتوى على هاتف ممسوك عموديًا: قص 4:5 هو بورتريه طويل يملأ شاشة الهاتف أكثر من مربع.</p>\n<p>نسبة 4:5 تناسب منشورات عمودية في وسائل التواصل الاجتماعي: تُعرض أكبر على الهاتف من منشور مربع، ما يجعل الصورة أبرز دون ملء الشاشة كلها. ونسبة 9:16 هي شاشة هاتف كاملة في وضع عمودي: إنها شكل القصص والريلز والفيديو العمودي، وتملأ الشاشة من حافة إلى حافة.</p>\n<p>والقصاصات العمودية تتطلب تأطيرًا دقيقًا: منظر واسع مضغوط في 9:16 يفقد معظم جانبيه، فهذه النسبة تناسب أشخاصًا منفردين لا مشاهد واسعة.</p>\n<h2 id=\"custom-ratios\">نسب مخصصة: عندما لا يناسب أي إعداد مسبق</h2>\n<p>أحيانًا لا تطابق أي نسبة قياسية وجهتك: حجم لافتة محدد أو غلاف كتاب أو نموذج بأبعاد ثابتة بالبكسلات يحتاج شكلًا مخصصًا.</p>\n<p>الوضع الحر في القصاص يتيح سحب الإطار إلى أي شكل: تعرض الأداة أبعاد الإخراج الدقيقة، فتستطيع مطابقة الحجم المطلوب بدقة. والنسب المخصصة تنفع أيضًا لقص تفصيل من صورة أكبر: فقرة واحدة من صفحة أو شعار من صورة أو وجه بين حشد تحتاج أشكالًا لا توفرها الإعدادات المسبقة.</p>\n<p>وعند استخدام نسبة مخصصة، دوّن أبعاد البكسلات التي تحتاجها أولًا: قص بالعين سهل الخطأ، بينما قص متحقق منه مقابل رقم دقيق.</p>\n<h2 id=\"ratio-vs-resolution\">النسبة مقابل الدقة: شيئان مختلفان</h2>\n<p>النسبة تصف الشكل، بينما الدقة تصف الحجم بالبكسلات: صورتان قد تشتركان في نسبة بدقة مختلفة جدًا، وصورتان قد تشتركان في دقة بنسب مختلفة.</p>\n<p>قص 1:1 من 500 في 500 بكسلًا وقص 1:1 من 2000 في 2000 بكسلًا لهما نفس الشكل، لكن الثاني يحمل ستة عشر ضعف البكسلات. وهذا مهم لأن منصة تحتاج 1000 بكسل ستمد قص 500 بكسل وتتركه ضبابيًا، مع أن الشكل كان صحيحًا: النسبة كانت جيدة والدقة كانت سيئة.</p>\n<p>راجع الرقمين دائمًا: القصاص يعرض أبعاد الإخراج، فتأكد من الشكل بالنسبة ومن الحجم بعدد البكسلات قبل التنزيل.</p>\n<h2 id=\"ratio-mistakes\">أخطاء تنشأ من النسبة الخطأ</h2>\n<p>أكثر خطأ شيوعًا قص إلى نسبة ثم مد النتيجة لتناسب شكلًا آخر: المد يشوه وجوهًا وأجسامًا، والضرر يُرى فورًا.</p>\n<p>خطأ آخر ترك منصة تعيد قص صورتك: صورة مربعة رُفعت كلافتة ستقصها المنصة، وستكون هي من يختار ما يقص، لا أنت. وينسى الناس أيضًا أن تغيير نسبة يتخلص من بكسلات: قص صورة واسعة إلى مربع يتخلص من الثلثين الأيسر والأيمن، وقد يحتويان الشخص.</p>\n<p>والحل اختيار النسبة قبل القص، حسب قواعد الوجهة: مراجعة خمس ثوانٍ لدليل أحجام المنصة تتجنب الأخطاء الثلاثة.</p>\n<h2 id=\"ratio-for-print\">نسب للطباعة</h2>\n<p>أحجام الطباعة لها نسبها الخاصة، ولا تطابق دائمًا أشكال الشاشة: طباعة 6 في 4 بوصات هي 3:2، وطباعة 10 في 8 بوصات هي 5:4، وصفحة A4 نحو 1.41:1.</p>\n<p>قبل الطباعة، راجع نسبة حجم الورق وقص لمطابقتها: صورة مقصوصة إلى 16:9 ستترك أشرطة بيضاء في طباعة 4:3، أو تفقد حوافها بقص الطباعة. والطباعة تحتاج دقة أيضًا لا شكلًا فقط: قص صغير مطبوع بحجم كبير سيبدو ناعمًا، فتأكد من عدد البكسلات إضافة إلى النسبة.</p>\n<p>وعند الشك، قص أكبر قليلًا من حجم الطباعة واترك المختبر يقص الزائد: هامش إضافي قليل أأمن من قص بالشكل الدقيق تمامًا.</p>\n<h2 id=\"ratio-workflow\">سير عمل لاختيار النسب</h2>\n<p>ابدأ بإدراج كل مكان ستظهر فيه الصورة: صورة يجب أن تكون صورة شخصية ولافتة وطباعة تحتاج ثلاثة قصاصات مختلفة من نفس الأصل.</p>\n<p>قص كل نسخة منفصلًا من الملف الأصلي: قص من قص يفقد جودة، بينما قصاصات جديدة من الأصل تبقى حادة. وسمِّ كل ملف بوجهته ونسبته، مثل avatar-1x1.png أو banner-16x9.png: أسماء واضحة تمنعك من رفع الشكل الخطأ إلى المكان الخطأ.</p>\n<p>واحتفظ بالملف الأصلي: الوجهات تغيّر قواعد أحجامها، وأصل محفوظ يتيح لك إعادة القص إلى نسبة جديدة دون البدء من نسخة تالفة.</p>\n<h2 id=\"ratio-cheat-sheet\">ورقة غش سريعة للنسب</h2>\n<p>استخدم 1:1 لصور شخصية ومنشورات في شبكة وأي شيء يُعرض في مربع أو دائرة: أبقِ الشخص ممركزًا بمساحة أعلاه.</p>\n<p>استخدم 4:3 لصور تقليدية ووثائق وطباعات على ورق قياسي: إنها شكل الصورة العام الأكثر أمانًا. واستخدم 3:2 لصور كاميرا تنوي طباعتها 6 في 4 بوصات: تطابق معيار الفيلم وإخراج معظم كاميرات DSLR.</p>\n<p>واستخدم 16:9 للافتات ومصغرات وشرائح: أبقِ المحتوى المهم في المركز، بعيدًا عن الحواف التي تقصها شاشات الهواتف.</p>\n<h2 id=\"ratio-for-video-thumbnails\">نسب لمصغرات فيديو</h2>\n<p>مصغرات الفيديو دائمًا تقريبًا 16:9، لأنها تذهب في مشغلات فيديو تستخدم الشكل العريض: مصغرة مقصوصة إلى أي نسبة أخرى ستمدها المنصة أو تعرضها بأشرطة.</p>\n<p>أبقِ الوجه والشخص الرئيسي كبيرين في قص مصغرة: مصغرة تُعرض صغيرة في خلاصة، فشخص صغير يختفي وكبير يجذب الانتباه. واترك مساحة لنص إذا نويت إضافة عنوان على المصغرة: قص 16:9 بالشخص في جانب ومساحة فارغة في الآخر يعطي النص مكانًا ليكون فيه.</p>\n<p>وراجع المصغرة على هاتف قبل النشر: قص يبدو جيدًا على الحاسوب قد يكون غير مقروء على شاشة صغيرة، حيث المصغرة لا تتجاوز بضعة سنتيمترات عرضًا.</p>\n<h2 id=\"ratio-for-ecommerce\">نسب للتجارة الإلكترونية وقوائم المنتجات</h2>\n<p>قوائم المنتجات غالبًا تطلب صورًا مربعة، لأن شبكة مربعات تتماشى جيدًا وتبدو احترافية: قص 1:1 هو الخيار الأكثر أمانًا لمعظم المتاجر.</p>\n<p>بعض الأسواق تطلب نسبة محددة، مثل 4:3 أو 3:2، وستقص صورتك إذا لم تطابق: راجع قواعد القائمة قبل القص لا بعده. والاتساق أهم من الإبداع في شبكة منتجات: قص كل منتج بنفس النسبة ونفس الهوامش، ليبدو الكتالوج مرتبًا وموثوقًا.</p>\n<p>ولصورة رئيسية في صفحة منتج، نسبة أوسع مثل 16:9 أو 3:2 تعمل أفضل: تُظهر المنتج في سياق، مع مساحة لخلفية أسلوب حياة حوله.</p>\n<h2 id=\"ratio-and-composition\">النسبة والتكوين: كيف يغيّر الشكل الإحساس</h2>\n<p>مربع يشعر بالهدوء والتوازن، لأن لا اتجاه يهيمن: يناسب صورًا شخصية وطبيعة صامتة وأي شيء يجب أن يشعر بالتمركز والثبات.</p>\n<p>نسبة واسعة تشعر بالانفتاح والسينمائية، لأن العين تسافر عبر الإطار: تناسب مناظر ومناظر مدن وأي مشهد حيث العرض هو النقطة. ونسبة عالية تشعر بالحميمية والتركيز، لأن العين تتحرك أعلى وأسفل في إطار ضيق: تناسب أشخاصًا منفردين، مثل شخص أو مبنى أو شجرة.</p>\n<p>اختر النسبة حسب الإحساس إضافة إلى الوجهة: منظر مقصوص إلى مربع يفقد إحساسه بالمساحة، بينما صورة شخصية مقصوصة واسعة تفقد إحساسها بالقرب.</p>\n<h2 id=\"ratio-changes-over-time\">النسب تتغير: كيف تبقى مواكبًا للمنصات</h2>\n<p>قواعد أحجام المنصات تتغير بانتظام، ونسبة عملت العام الماضي قد لا تناسب هذا العام: خلاصة أرادت مربعات قد تفضل الآن بورتريه.</p>\n<p>احتفظ بالملف الأصلي لكل صورة مهمة: عندما تغيّر منصة قواعدها، تستطيع إعادة قص الأصل إلى النسبة الجديدة بدل مد قص قديم. وراجع دليل أحجام كل منصة قبل القص لها: مراجعة دقيقتين تتجنب قصًا ستعيد المنصة قصه نيابة عنك، وبشكل سيئ.</p>\n<p>اصنع قائمة قصيرة بالنسب التي تستخدمها أكثر، وحدّثها عندما تغيّر منصة: ملاحظة على مكتبك تقول صورة شخصية 1:1 ولافتة 16:9 وقصة 9:16 توفر وقتًا في كل جلسة.</p>\n<p>استخدم 4:5 لمنشورات عمودية تحتاج التميز في خلاصة الهاتف، و9:16 لقصص بملء الشاشة وفيديو عمودي: وللخطوات العملية، راجع <a href=\"/ar/blog/kayfiyya-qass-as-sura/\">كيف تقص صورة</a>، وللدليل الكامل راجع <a href=\"/ar/blog/dalil-qass-as-suwar/\">دليل قصاص الصور الكامل</a>. وإذا احتجت تغيير حجم صورة كاملة لا قصها، استخدم <a href=\"/ar/taghyir-hajm-as-suwar/\">مغير حجم الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ماذا تعني 1:1 في القص؟","answer":"تعني أن العرض والارتفاع متساويان، فالقص مربع مثالي: قص 1:1 يناسب صورًا شخصية ومنشورات في شبكة. وأبقِ الشخص ممركزًا بمساحة أعلاه، لأن المنصات تعرض صورًا شخصية مربعة كدوائر."},{"question":"أي نسبة يجب أن أستخدم لمصغرة يوتيوب؟","answer":"استخدم 16:9، الشكل العريض القياسي، الذي يطابق حجم مصغرة 1280 في 720 بكسلًا: أبقِ الشخص الرئيسي وأي نص في المركز، لأن الحواف قد تُقص على شاشات صغيرة."},{"question":"هل أستطيع قص صورة إلى نسبة لم تصور بها كاميرتي؟","answer":"نعم، القص إلى نسبة جديدة يزيل ببساطة بكسلات من الحواف حتى يطابق الشكل: صورة واسعة قد تصبح مربعة، ومربع قد يصبح لافتة واسعة، ما دامت المنطقة المحفوظة تحتوي الشخص."},{"question":"أي نسبة يجب أن أستخدم لطباعة صورة؟","answer":"طابق حجم الورق: 3:2 لطباعة 6 في 4 بوصات، و5:4 لطباعة 10 في 8 بوصات، ونحو 1.41:1 لـA4: راجع النسبة وعدد البكسلات معًا، لأن قصًا صغيرًا مطبوعًا بحجم كبير سيبدو ناعمًا."},{"question":"لماذا يعيد إنستغرام قص صورتي بعد رفعها؟","answer":"يعيد إنستغرام قص صور لا تطابق نسبه المفضلة للمساحة التي اخترتها: قص إلى النسبة الصحيحة قبل الرفع، مثل 1:1 لمنشور في شبكة أو 4:5 لمنشور عمودي، وستتوقف إعادة القص."},{"question":"ما الفرق بين النسبة والدقة؟","answer":"النسبة هي شكل الصورة، مثل 16:9، بينما الدقة هي الحجم بالبكسلات، مثل 1920 في 1080: صورتان قد تشتركان في نسبة بدقة مختلفة. وراجع الاثنين دائمًا قبل التنزيل."}];
